import java.io.*;
import java.util.*;

public class Main {
    static void solve() {
        int n = ni();
        long tmp = nl();
        if(n <= tmp) {
            out.println(0);
            return;
        }
        int k = (int)tmp;
        preFact(400000);
        long answer = 0;
        int sign = 1;
        long totalComb = cmb(n, n-k);
        for(int i=n-k;i>=1;i--) {
            answer += sign * cmb(n-k, i) * pow(i, n);
            answer %= mod;
            if(answer < 0) answer += mod;
            sign *= -1;
        }
        answer *= totalComb; answer %= mod;
        if(k != 0) answer *= 2; answer %= mod;
        if(answer < 0) answer += mod;
        out.println(answer);
    }

    static long[] fact, revFact;

    static void preFact(int n) {
        fact = new long[n + 1];
        revFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 0; i < n; i++) {
            fact[i + 1] = mul(i + 1, fact[i]);
        }
        revFact[n] = div(1, fact[n]);
        for (int i = n - 1; i >= 0; i--) {
            revFact[i] = mul(revFact[i + 1], i + 1);
        }
    }

    static long cmb(int a, int b) {
        if (a < b) return 0;
        long af = fact[a];
        long bf = revFact[b];
        long abf = revFact[a - b];
        return mul(mul(af, bf), abf);
    }

    static final long mod = 998244353;

    static long pow(long x, long y) {
        if (y < 0) return 0;
        long res = 1;
        long base = x % mod;
        long exp = y;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    static long mul(long x, long y) {
        return (x * y) % mod;
    }

    static long div(long x, long y) {
        return (x * pow(y, mod - 2)) % mod;
    }

    static int ni() {
        return Integer.parseInt(ns());
    }

    static long nl() {
        return Long.parseLong(ns());
    }

    static String ns() {
        try {
            int b = skip();
            StringBuilder sb = new StringBuilder();
            while (!(isSpaceChar(b))) {
                sb.appendCodePoint(b);
                b = readByte();
            }
            return sb.toString();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    static int skip() throws IOException {
        int b;
        while ((b = readByte()) != -1 && isSpaceChar(b))
            ;
        return b;
    }

    static boolean isSpaceChar(int c) {
        return !(c >= 33 && c <= 126);
    }

    static InputStream is = System.in;
    static PrintWriter out = new PrintWriter(System.out);
    static byte[] inbuf = new byte[1024];
    static int lenbuf = 0, ptrbuf = 0;

    static int readByte() throws IOException {
        if (lenbuf == -1) throw new InputMismatchException();
        if (ptrbuf >= lenbuf) {
            ptrbuf = 0;
            lenbuf = is.read(inbuf);
            if (lenbuf <= 0) return -1;
        }
        return inbuf[ptrbuf++];
    }

    public static void main(String[] args) {
        solve();
        out.flush();
    }
}
